dashboard.definition:
{
	"title": "Detection & Response",
	"description": "Surface access-related detections and the response actions that contain risk.",
	"inputs": {
		"input_time_range": {
			"options": {
				"defaultValue": "-24h@h,now",
				"token": "time_tok"
			},
			"title": "Time Range",
			"type": "input.timerange"
		}
	},
	"defaults": {
		"visualizations": {
			"global": {
				"showLastUpdated": true,
				"showProgressBar": true
			}
		}
	},
	"visualizations": {
		"viz_header_bg": {
			"type": "splunk.rectangle",
			"options": {
				"fillColor": "#16283c",
				"strokeColor": "rgba(53,207,245,0.42)"
			}
		},
		"viz_header_icon": {
			"type": "splunk.image",
			"title": "Zero Trust Access",
			"options": {
				"preserveAspectRatio": true,
				"src": "/static/app/splunk-cisco-dashboards/images/overview/secure-networking/zero-trust-access.svg"
			}
		},
		"viz_header": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "transparent",
				"fontColor": "#e8f1fb",
				"markdown": "# Detection & Response\nSurface access-related detections and the response actions that contain risk."
			}
		},
		"viz_xdr_incident_status_severity_pressure": {
			"type": "splunk.table",
			"title": "XDR - Incident - Status and Severity Pressure Matrix",
			"dataSources": {
				"primary": "ds_xdr_incident_status_severity_pressure"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Summarizes Cisco XDR incident pressure by lifecycle status and severity, including unique incident volume and average global score."
		},
		"viz_xdr_incident_global_risk_leaderboard": {
			"type": "splunk.table",
			"title": "XDR - Incident - Global Risk and Event Pressure Leaderboard",
			"dataSources": {
				"primary": "ds_xdr_incident_global_risk_leaderboard"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Ranks Cisco XDR incidents by global risk score and repeated event pressure with status, severity, and confidence context."
		},
		"viz_xdr_aa_forensic_network_internal_service_pressure": {
			"type": "splunk.table",
			"title": "XDR - Attack Analyzer - Forensic Network Service Pressure",
			"dataSources": {
				"primary": "ds_xdr_aa_forensic_network_internal_service_pressure"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Ranks protocol, destination, and service combinations in sandbox network telemetry to expose dominant communication patterns."
		},
		"viz_xdr_aa_forensic_network_external_egress_watch": {
			"type": "splunk.table",
			"title": "XDR - Attack Analyzer - Forensic Network External Egress Watch",
			"dataSources": {
				"primary": "ds_xdr_aa_forensic_network_external_egress_watch"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Isolates external destination flows from sandbox telemetry, including management-port and encrypted-egress risk labels."
		},
		"viz_xdr_aa_forensic_files_network_source_hotspots": {
			"type": "splunk.table",
			"title": "XDR - Attack Analyzer - Forensic Files Network Source Hotspots",
			"dataSources": {
				"primary": "ds_xdr_aa_forensic_files_network_source_hotspots"
			},
			"options": {
				"backgroundColor": "#0f1a2a",
				"count": 20,
				"fontSize": "small",
				"showInternalFields": false
			},
			"description": "Ranks upstream network sources that delivered the most forensic file artifacts and unique hashes into analysis jobs."
		},
		"viz_design_context": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#111f31",
				"fontColor": "#e8f1fb",
				"markdown": "**Audience:** SOC analysts and incident responders  •  **Sources:** Cisco XDR incidents and Attack Analyzer forensic telemetry  •  **Reading guide:** Prioritize lifecycle and severity pressure, then open the supporting forensic evidence.  •  **Freshness:** Uses the dashboard time range"
			}
		},
		"viz_design_section": {
			"type": "splunk.markdown",
			"title": "",
			"showLastUpdated": false,
			"showProgressBar": false,
			"options": {
				"backgroundColor": "#111f31",
				"fontColor": "#e8f1fb",
				"markdown": "### Incident pressure\nPrioritize lifecycle and severity pressure, then open the supporting forensic evidence."
			}
		}
	},
	"dataSources": {
		"ds_xdr_incident_status_severity_pressure": {
			"name": "XDR - Incident - Status and Severity Pressure Matrix",
			"options": {
				"ref": "xdr_incident_status_severity_pressure",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_xdr_incident_global_risk_leaderboard": {
			"name": "XDR - Incident - Global Risk and Event Pressure Leaderboard",
			"options": {
				"ref": "xdr_incident_global_risk_leaderboard",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_xdr_aa_forensic_network_internal_service_pressure": {
			"name": "XDR - Attack Analyzer - Forensic Network Service Pressure",
			"options": {
				"ref": "xdr_aa_forensic_network_internal_service_pressure",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_xdr_aa_forensic_network_external_egress_watch": {
			"name": "XDR - Attack Analyzer - Forensic Network External Egress Watch",
			"options": {
				"ref": "xdr_aa_forensic_network_external_egress_watch",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		},
		"ds_xdr_aa_forensic_files_network_source_hotspots": {
			"name": "XDR - Attack Analyzer - Forensic Files Network Source Hotspots",
			"options": {
				"ref": "xdr_aa_forensic_files_network_source_hotspots",
				"queryParameters": {
					"earliest": "$time_tok.earliest$",
					"latest": "$time_tok.latest$"
				}
			},
			"type": "ds.searchbase"
		}
	},
	"layout": {
		"globalInputs": [
			"input_time_range"
		],
		"layoutDefinitions": {
			"layout_overview": {
				"options": {
					"backgroundColor": "#07101d",
					"display": "auto-scale",
					"height": 1626,
					"width": 1440
				},
				"structure": [
					{
						"item": "viz_header_bg",
						"position": {
							"x": 20,
							"y": 0,
							"w": 1400,
							"h": 118
						},
						"type": "block"
					},
					{
						"item": "viz_header_icon",
						"position": {
							"x": 36,
							"y": 19,
							"w": 80,
							"h": 80
						},
						"type": "block"
					},
					{
						"item": "viz_header",
						"position": {
							"x": 132,
							"y": 8,
							"w": 1268,
							"h": 102
						},
						"type": "block"
					},
					{
						"item": "viz_design_context",
						"position": {
							"x": 20,
							"y": 138,
							"w": 1400,
							"h": 92
						},
						"type": "block"
					},
					{
						"item": "viz_design_section",
						"position": {
							"x": 20,
							"y": 250,
							"w": 1400,
							"h": 72
						},
						"type": "block"
					},
					{
						"item": "viz_xdr_incident_status_severity_pressure",
						"position": {
							"x": 20,
							"y": 342,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_xdr_incident_global_risk_leaderboard",
						"position": {
							"x": 730,
							"y": 342,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_xdr_aa_forensic_network_internal_service_pressure",
						"position": {
							"x": 20,
							"y": 770,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_xdr_aa_forensic_network_external_egress_watch",
						"position": {
							"x": 730,
							"y": 770,
							"w": 690,
							"h": 408
						},
						"type": "block"
					},
					{
						"item": "viz_xdr_aa_forensic_files_network_source_hotspots",
						"position": {
							"x": 20,
							"y": 1198,
							"w": 690,
							"h": 408
						},
						"type": "block"
					}
				],
				"type": "absolute"
			}
		},
		"options": {
			"showTitleAndDescription": false,
			"submitButton": false,
			"submitOnDashboardLoad": true
		},
		"tabs": {
			"items": [
				{
					"label": "overview",
					"layoutId": "layout_overview"
				}
			]
		}
	},
	"applicationProperties": {
		"collapseNavigation": false,
		"hideEdit": false,
		"hideExport": false
	}
}
